namespace RecipeShare.Services;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
}

public class RecipeService
{
    private readonly List<Recipe> _recipes =
    [
        new()
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Description = "A simple yet delicious pizza with fresh tomatoes, mozzarella, and basil.",
            Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
            Steps = ["Preheat oven to 475°F.", "Roll out dough on a floured surface.", "Spread crushed tomatoes evenly.", "Add torn mozzarella pieces.", "Bake for 10–12 minutes until crust is golden.", "Top with fresh basil and a drizzle of olive oil."]
        },
        new()
        {
            Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
            Description = "Creamy Roman pasta with eggs, pecorino, and guanciale.",
            Ingredients = ["Spaghetti", "Guanciale", "Eggs", "Pecorino Romano", "Black pepper"],
            Steps = ["Cook spaghetti in salted water until al dente.", "Crisp guanciale in a pan over medium heat.", "Whisk eggs with grated pecorino and pepper.", "Drain pasta, reserving some water.", "Toss hot pasta with guanciale off heat.", "Add egg mixture, tossing quickly to create a creamy sauce."]
        },
        new()
        {
            Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
            Description = "Tender chicken pieces in a rich, spiced tomato-cream sauce.",
            Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Tomato sauce", "Heavy cream", "Onion", "Garlic", "Ginger"],
            Steps = ["Marinate chicken in yogurt and spices for 1 hour.", "Grill or broil chicken until charred.", "Sauté onion, garlic, and ginger.", "Add tomato sauce and simmer 15 minutes.", "Stir in cream and garam masala.", "Add chicken pieces and simmer 10 minutes."]
        },
        new()
        {
            Id = 4, Title = "Vegetable Pad Thai", Category = "Thai",
            Description = "Stir-fried rice noodles with vegetables, peanuts, and tangy sauce.",
            Ingredients = ["Rice noodles", "Tofu", "Bean sprouts", "Scallions", "Peanuts", "Lime", "Tamarind paste", "Fish sauce", "Sugar"],
            Steps = ["Soak rice noodles in warm water for 20 minutes.", "Mix tamarind paste, fish sauce, and sugar for the sauce.", "Stir-fry tofu until golden.", "Add noodles and sauce, toss until coated.", "Add bean sprouts and scallions.", "Serve with crushed peanuts and lime wedges."]
        },
        new()
        {
            Id = 5, Title = "Beef Tacos", Category = "Mexican",
            Description = "Seasoned ground beef in warm tortillas with fresh toppings.",
            Ingredients = ["Ground beef", "Taco seasoning", "Corn tortillas", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Salsa"],
            Steps = ["Brown ground beef in a skillet.", "Add taco seasoning and water, simmer 5 minutes.", "Warm tortillas in a dry pan.", "Fill tortillas with seasoned beef.", "Top with lettuce, tomato, cheese, sour cream, and salsa.", "Serve immediately."]
        },
        new()
        {
            Id = 6, Title = "Guacamole", Category = "Mexican",
            Description = "Fresh avocado dip with lime, cilantro, and jalapeño.",
            Ingredients = ["Avocados", "Lime juice", "Cilantro", "Red onion", "Jalapeño", "Salt", "Tomato"],
            Steps = ["Halve avocados and remove pits.", "Mash avocado to desired consistency.", "Stir in lime juice, diced onion, and jalapeño.", "Fold in chopped cilantro and diced tomato.", "Season with salt to taste.", "Serve with tortilla chips."]
        },
        new()
        {
            Id = 7, Title = "Miso Ramen", Category = "Japanese",
            Description = "Hearty noodle soup with miso broth, pork, and soft-boiled egg.",
            Ingredients = ["Ramen noodles", "Miso paste", "Chicken broth", "Pork belly", "Soft-boiled egg", "Scallions", "Corn", "Nori"],
            Steps = ["Simmer chicken broth and whisk in miso paste.", "Cook ramen noodles according to package.", "Sear sliced pork belly until caramelized.", "Divide noodles into bowls.", "Ladle hot miso broth over noodles.", "Top with pork, halved egg, scallions, corn, and nori."]
        },
        new()
        {
            Id = 8, Title = "Chocolate Lava Cake", Category = "Desserts",
            Description = "Rich individual chocolate cakes with a molten center.",
            Ingredients = ["Dark chocolate", "Butter", "Eggs", "Sugar", "Flour", "Vanilla extract"],
            Steps = ["Preheat oven to 425°F. Grease ramekins.", "Melt chocolate and butter together.", "Whisk eggs and sugar until thick.", "Fold chocolate mixture into eggs.", "Add flour and vanilla, fold gently.", "Bake 12–14 minutes until edges are set but center jiggles."]
        }
    ];

    private readonly Dictionary<int, List<int>> _ratings = [];

    public List<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public List<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public double GetAverageRating(int recipeId)
    {
        if (_ratings.TryGetValue(recipeId, out var ratings) && ratings.Count > 0)
            return ratings.Average();
        return 0;
    }

    public int GetRatingCount(int recipeId) =>
        _ratings.TryGetValue(recipeId, out var ratings) ? ratings.Count : 0;

    public void AddRating(int recipeId, int stars)
    {
        if (stars < 1 || stars > 5) return;
        if (!_ratings.ContainsKey(recipeId))
            _ratings[recipeId] = [];
        _ratings[recipeId].Add(stars);
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Count > 0 ? _recipes.Max(r => r.Id) + 1 : 1;
        _recipes.Add(recipe);
    }
}

