arguments.new_str:
@page "/"

<PageTitle>RecipeShare — Home</PageTitle>

<h1>🍽️ Welcome to RecipeShare</h1>
<p class="lead">Discover and share your favorite recipes from around the world.</p>

<h2 class="mt-4">Browse by Category</h2>

<div class="row mt-3">
    @foreach (var category in Categories)
    {
        <div class="col-md-4 mb-3">
            <div class="card h-100">
                <div class="card-body">
                    <h5 class="card-title">@GetCategoryEmoji(category) @category</h5>
                    <p class="card-text">@GetCategoryDescription(category)</p>
                    <a href="category/@category" class="btn btn-primary">Browse Recipes</a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Inject] private RecipeShare.Services.RecipeService RecipeService { get; set; } = default!;

    private List<string> Categories { get; set; } = [];

    protected override void OnInitialized()
    {
        Categories = RecipeService.GetCategories();
    }

    private static string GetCategoryEmoji(string category) => category switch
    {
        "Italian" => "🍝",
        "Indian" => "🍛",
        "Thai" => "🍜",
        "Mexican" => "🌮",
        "Japanese" => "🍣",
        "Desserts" => "🍰",
        _ => "🍴"
    };

    private static string GetCategoryDescription(string category) => category switch
    {
        "Italian" => "Classic pasta, pizza, and Mediterranean flavors.",
        "Indian" => "Bold spices and rich, aromatic dishes.",
        "Thai" => "Fresh herbs, tangy sauces, and vibrant noodles.",
        "Mexican" => "Tacos, salsas, and zesty Latin flavors.",
        "Japanese" => "Umami-rich soups, sushi, and comfort food.",
        "Desserts" => "Sweet treats and indulgent baked goods.",
        _ => "Explore delicious recipes."
    };
}

arguments.file_text:
@page "/category/{CategoryName}"

<PageTitle>@CategoryName Recipes — RecipeShare</PageTitle>

<h1>@GetCategoryEmoji(CategoryName) @CategoryName Recipes</h1>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">@CategoryName</li>
    </ol>
</nav>

@if (Recipes.Count == 0)
{
    <p class="text-muted">No recipes found in this category.</p>
}
else
{
    <div class="row">
        @foreach (var recipe in Recipes)
        {
            <div class="col-md-6 mb-3">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">@recipe.Description</p>
                        <a href="recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;
    [Inject] private RecipeShare.Services.RecipeService RecipeService { get; set; } = default!;

    private List<RecipeShare.Services.Recipe> Recipes { get; set; } = [];

    protected override void OnParametersSet()
    {
        Recipes = RecipeService.GetByCategory(CategoryName);
    }

    private static string GetCategoryEmoji(string category) => category switch
    {
        "Italian" => "🍝",
        "Indian" => "🍛",
        "Thai" => "🍜",
        "Mexican" => "🌮",
        "Japanese" => "🍣",
        "Desserts" => "🍰",
        _ => "🍴"
    };
}

@page "/recipe/{RecipeId:int}"

<PageTitle>@(Recipe?.Title ?? "Recipe") — RecipeShare</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        @if (Recipe is not null)
        {
            <li class="breadcrumb-item"><a href="category/@Recipe.Category">@Recipe.Category</a></li>
            <li class="breadcrumb-item active">@Recipe.Title</li>
        }
    </ol>
</nav>

@if (Recipe is null)
{
    <p class="text-muted">Recipe not found.</p>
}
else
{
    <h1>@Recipe.Title</h1>
    <p class="lead">@Recipe.Description</p>

    <StarRating RecipeId="Recipe.Id" @rendermode="InteractiveServer" />

    <div class="row mt-4">
        <div class="col-md-5">
            <h3>🥘 Ingredients</h3>
            <ul class="list-group">
                @foreach (var ingredient in Recipe.Ingredients)
                {
                    <li class="list-group-item">@ingredient</li>
                }
            </ul>
        </div>

        <div class="col-md-7">
            <h3>📝 Steps</h3>
            <ol class="list-group list-group-numbered">
                @foreach (var step in Recipe.Steps)
                {
                    <li class="list-group-item">@step</li>
                }
            </ol>
        </div>
    </div>
