@page "/recipe/{RecipeId:int}"

<PageTitle>@(Recipe?.Title ?? "Recipe") — RecipeShare</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        @if (Recipe is not null)
        {
            <li class="breadcrumb-item"><a href="category/@Recipe.Category">@Recipe.Category</a></li>
            <li class="breadcrumb-item active">@Recipe.Title</li>
        }
    </ol>
</nav>

@if (Recipe is null)
{
    <p class="text-muted">Recipe not found.</p>
}
else
{
    <h1>@Recipe.Title</h1>
    <p class="lead">@Recipe.Description</p>

    <StarRating RecipeId="Recipe.Id" @rendermode="InteractiveServer" />

    <div class="row mt-4">
        <div class="col-md-5">
            <h3>🥘 Ingredients</h3>
            <ul class="list-group">
                @foreach (var ingredient in Recipe.Ingredients)
                {
                    <li class="list-group-item">@ingredient</li>
                }
            </ul>
        </div>

        <div class="col-md-7">
            <h3>📝 Steps</h3>
            <ol class="list-group list-group-numbered">
                @foreach (var step in Recipe.Steps)
                {
                    <li class="list-group-item">@step</li>
                }
            </ol>
        </div>
    </div>
}

@code {
    [Parameter] public int RecipeId { get; set; }
    [Inject] private RecipeShare.Services.RecipeService RecipeService { get; set; } = default!;

    private RecipeShare.Services.Recipe? Recipe { get; set; }

    protected override void OnParametersSet()
    {
        Recipe = RecipeService.GetById(RecipeId);
    }
}

@rendermode InteractiveServer

<div class="my-3 p-3 border rounded bg-light">
    <h5 class="mb-2">Rate this recipe</h5>
    <div style="font-size: 1.8rem; cursor: pointer; user-select: none;">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span @onclick="() => Rate(star)"
                  @onmouseover="() => hoverStar = star"
                  @onmouseout="() => hoverStar = 0"
                  style="color: @(star <= DisplayStar ? "#ffc107" : "#dee2e6"); transition: color 0.15s;">
                ★
            </span>
        }
    </div>
    @if (AverageRating > 0)
    {
        <small class="text-muted">
            @AverageRating.ToString("0.0") avg · @RatingCount @(RatingCount == 1 ? "rating" : "ratings")
        </small>
    }
    @if (justRated)
    {
        <div class="text-success mt-1"><small>✓ Thanks for rating!</small></div>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Inject] private RecipeShare.Services.RecipeService RecipeService { get; set; } = default!;

    private int hoverStar;
    private int selectedStar;
    private bool justRated;
    private double AverageRating;
    private int RatingCount;

    private int DisplayStar => hoverStar > 0 ? hoverStar : selectedStar;

    protected override void OnParametersSet()
    {
        RefreshRating();
    }

    private void Rate(int stars)
    {
        RecipeService.AddRating(RecipeId, stars);
        selectedStar = stars;
        justRated = true;
        RefreshRating();
    }

    private void RefreshRating()
    {
        AverageRating = RecipeService.GetAverageRating(RecipeId);
        RatingCount = RecipeService.GetRatingCount(RecipeId);
    }
}

